// --- headlines.js
// Pure functions: plain values in, { tone, text, sub? } out. No DOM, no hass.
// tone is one of "ok" | "warn" | "alert" | "info" and drives the accent colour.
// Rule: never assert a state we could not read — missing values are null.

function relTime(minutes) {
  if (minutes == null || Number.isNaN(minutes)) return null;
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${Math.round(minutes)} min ago`;
  const h = minutes / 60;
  if (h < 24) return `${Math.round(h)} h ago`;
  return `${Math.round(h / 24)} d ago`;
}

const ALARM_WORDS = {
  disarmed: "off",
  armed_home: "armed (home)",
  armed_away: "armed (away)",
  armed_night: "armed (night)",
  arming: "arming",
  pending: "about to go off",
  triggered: "going off",
};

function alarmWord(state) {
  return ALARM_WORDS[state] ?? null;
}

function list(names) {
  if (names.length <= 1) return names.join("");
  return `${names.slice(0, -1).join(", ")} and ${names.at(-1)}`;
}

// --- Home -----------------------------------------------------------------

function homeHeadline({ alarm, lock, jammed, garage, personNow, insideTemp, openings = [] }) {
  const sub = [];
  const aw = alarmWord(alarm);
  if (aw) sub.push(`Alarm is ${aw}.`);
  if (insideTemp != null) sub.push(`It's ${Math.round(insideTemp)}° inside.`);
  const subText = sub.join(" ") || null;

  if (alarm === "triggered") return { tone: "alert", text: "The alarm is going off.", sub: subText };
  if (jammed) return { tone: "alert", text: "The front door lock is jammed.", sub: subText };
  if (personNow) return { tone: "alert", text: `Someone is at the ${personNow} camera.`, sub: subText };

  const problems = [];
  if (lock === "unlocked") problems.push("the front door is unlocked");
  if (garage === "open" || garage === "opening") problems.push("the garage is open");
  const open = openings.filter((o) => o.open).map((o) => o.name);
  if (open.length) problems.push(`${list(open)} ${open.length === 1 ? "is" : "are"} open`);
  if (problems.length) {
    const t = list(problems);
    return { tone: "warn", text: `${t[0].toUpperCase()}${t.slice(1)}.`, sub: subText };
  }
  if (lock == null && garage == null) return { tone: "info", text: "Can't read the doors right now.", sub: subText };
  return { tone: "ok", text: "All quiet at home.", sub: subText };
}

function greeting(hour) {
  if (hour < 5) return "Good night";
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  if (hour < 22) return "Good evening";
  return "Good night";
}

function whoIsHome(people) {
  const known = people.filter((p) => p.state != null);
  const home = known.filter((p) => p.state === "home");
  if (!known.length) return { tone: "info", text: "—", sub: "Who's home" };
  if (home.length === known.length) return { tone: "ok", text: known.length === 2 ? "Both home" : "Everyone home", sub: "Together" };
  if (!home.length) return { tone: "info", text: "Nobody home", sub: "House is empty" };
  return { tone: "info", text: `${list(home.map((p) => p.name))} home`, sub: `${list(known.filter((p) => p.state !== "home").map((p) => p.name))} out` };
}

// --- Security -------------------------------------------------------------

function securityHeadline({ alarm, lock, jammed, garage, lastPerson, openings = [] }) {
  const sub = alarm === "disarmed"
    ? "Arm it when you leave, or Alarmo arms itself at night."
    : alarmWord(alarm) ? `Alarm is ${alarmWord(alarm)}.` : null;

  if (alarm === "triggered") return { tone: "alert", text: "The alarm is going off.", sub };
  if (jammed) return { tone: "alert", text: "The front door lock is jammed.", sub };

  const parts = [];
  const secure = lock === "locked" && garage === "closed" && !openings.some((o) => o.open);
  if (lock === "unlocked") parts.push("Front door is unlocked");
  if (garage === "open" || garage === "opening") parts.push("Garage is open");
  const open = openings.filter((o) => o.open).map((o) => o.name);
  if (open.length) parts.push(`${list(open)} open`);

  let text;
  let tone;
  if (parts.length) { text = `${parts.join(". ")}.`; tone = "warn"; }
  else if (secure) { text = "Locked up."; tone = "ok"; }
  else { text = "Can't confirm everything is locked."; tone = "info"; }

  if (lastPerson && lastPerson.minutes != null && lastPerson.minutes < 30) {
    const when = lastPerson.now ? "now" : relTime(lastPerson.minutes);
    text += ` Person at ${lastPerson.camera} ${when}.`;
    if (tone === "ok") tone = lastPerson.now ? "alert" : "info";
  }
  return { tone, text, sub };
}

// --- Cameras --------------------------------------------------------------

// cams: [{ name, personNow, minutesSincePerson }] (minutesSincePerson = time since
// the person sensor last changed while it is off; null when unknown)
function camerasHeadline(cams) {
  const now = cams.filter((c) => c.personNow);
  if (now.length) return { tone: "alert", text: `Someone at the ${list(now.map((c) => c.name.toLowerCase()))} camera${now.length > 1 ? "s" : ""} now.` };
  const recent = cams
    .filter((c) => c.minutesSincePerson != null)
    .sort((a, b) => a.minutesSincePerson - b.minutesSincePerson);
  if (recent.length && recent[0].minutesSincePerson < 60) {
    return {
      tone: "info",
      text: `Person at the ${recent[0].name.toLowerCase()} camera ${relTime(recent[0].minutesSincePerson)}.`,
      sub: "Quiet everywhere else.",
    };
  }
  return { tone: "ok", text: "No one around.", sub: recent.length ? `Last person ${relTime(recent[0].minutesSincePerson)} at ${recent[0].name.toLowerCase()}.` : null };
}

// --- Car ------------------------------------------------------------------

function carHeadline({ location, garageCarInside, charging, cable, battery, limit, minutesToFull, open = [] }) {
  let text;
  if (location === "home") text = garageCarInside ? "In the garage" : "At home";
  else if (location == null || location === "unknown" || location === "unavailable") text = "Location unknown";
  else if (location === "not_home") text = "Away";
  else text = `At ${location}`;

  let sub;
  if (charging === "charging") {
    sub = minutesToFull ? `Charging to ${limit}% · ${relTime(minutesToFull).replace(" ago", "")} left` : `Charging to ${limit}%`;
  } else if (charging === "complete") sub = `Done charging at ${battery}%`;
  else if (cable) sub = "Plugged in, not charging";
  else sub = "Not plugged in";

  const tone = open.length ? "warn" : "ok";
  if (open.length) sub = `${list(open)} open · ${sub}`;
  return { tone, text, sub };
}

// --- Climate --------------------------------------------------------------

function thermostatHeadline({ mode, action, target, low, high }) {
  const t = (v) => (v == null ? "—" : `${Math.round(v * 2) / 2}°`);
  if (mode == null || mode === "unavailable") return { tone: "info", text: "Thermostat unavailable" };
  if (mode === "off") return { tone: "info", text: "Thermostat is off" };
  if (mode === "heat_cool") {
    if (action === "heating") return { tone: "warn", text: `Heating to ${t(low)}` };
    if (action === "cooling") return { tone: "info", text: `Cooling to ${t(high)}` };
    return { tone: "ok", text: `Holding ${t(low)}–${t(high)}` };
  }
  if (action === "heating") return { tone: "warn", text: `Heating to ${t(target)}` };
  if (action === "cooling") return { tone: "info", text: `Cooling to ${t(target)}` };
  return { tone: "ok", text: `Holding at ${t(target)}` };
}

function roomsHeadline(rooms) {
  const r = rooms.filter((x) => x.temp != null);
  if (!r.length) return { tone: "info", text: "No room temperatures yet." };
  if (r.length === 1) return { tone: "ok", text: `${r[0].name} is ${Math.round(r[0].temp)}°.` };
  const sorted = [...r].sort((a, b) => b.temp - a.temp);
  const diff = Math.round(sorted[0].temp - sorted.at(-1).temp);
  if (diff < 2) return { tone: "ok", text: "Every room is within a degree or two." };
  return { tone: diff >= 6 ? "warn" : "ok", text: `${sorted[0].name} is ${diff}° warmer than ${sorted.at(-1).name.toLowerCase()}.` };
}

function billHeadline({ toDate, forecast }) {
  if (toDate == null && forecast == null) return { tone: "info", text: "No bill data." };
  if (forecast == null) return { tone: "info", text: `$${Math.round(toDate)} so far this bill.` };
  return { tone: "info", text: `On pace for $${Math.round(forecast)} this bill.`, sub: toDate != null ? `$${Math.round(toDate)} so far.` : null };
}

// --- Lights ---------------------------------------------------------------

// lights: [{ name, floor, on }]  (on: true/false/null for unavailable)
function lightsHeadline(lights) {
  const on = lights.filter((l) => l.on === true);
  if (!on.length) return { tone: "ok", text: "All lights are off." };
  if (on.length === 1) return { tone: "info", text: `1 light on: ${on[0].name}.` };
  const floors = [...new Set(on.map((l) => l.floor).filter(Boolean))];
  const where = floors.length === 1 ? `, all ${floors[0].toLowerCase()}` : floors.length > 1 ? ", upstairs and down" : "";
  return { tone: "info", text: `${on.length} lights on${where}.` };
}

// --- base.js

// Send a browser-side failure to HA's system log so it shows in `ha core logs`
// (logger "stonebridge"). Card errors otherwise exist only in the browser console.
function report(message, hass) {
  console.error(`stonebridge: ${message}`);
  const h = hass ?? document.querySelector("home-assistant")?.hass;
  h?.callWS?.({ type: "system_log/write", logger: "stonebridge", level: "error", message: String(message).slice(0, 2000) })
    .catch(() => {});
}

// Last person seen per Frigate camera, from Frigate's own event history (via the
// Frigate integration's websocket API). Entity last_changed is NOT usable for
// this: HA resets it on every restart, which made every camera read "18 min ago".
// Shared by all cards; refreshed at most once a minute. null = unknown.
const personCache = { at: 0, times: null, inflight: null, listeners: new Set() };
function personTimes(hass, onUpdate) {
  personCache.listeners.add(onUpdate);
  if (!personCache.inflight && Date.now() - personCache.at > 60_000) {
    personCache.at = Date.now();
    personCache.inflight = hass.callWS({ type: "frigate/events/get", instance_id: "frigate", labels: ["person"], limit: 100 })
      .then((raw) => {
        const times = {};
        for (const e of typeof raw === "string" ? JSON.parse(raw) : raw) {
          const t = e.end_time ?? e.start_time;
          if (!(e.camera in times) || t > times[e.camera]) times[e.camera] = t;
        }
        personCache.times = times;
      })
      .catch((e) => { personCache.times = null; report(`frigate/events/get failed: ${e?.message ?? JSON.stringify(e)}`, hass); })
      .finally(() => { personCache.inflight = null; personCache.listeners.forEach((f) => f()); });
  }
  return personCache.times;
}

const BAD = new Set(["unavailable", "unknown", "", undefined, null]);

// Shared card base. Subclasses implement:
//   entities()   -> array of entity ids this card reads (used to skip re-renders)
//   render()     -> HTML string
//   handle(action, el) -> called on taps of [data-action] elements
// and may set static `sensitive` actions that need a confirming second tap.
class SbCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._pending = null;
    this.shadowRoot.addEventListener("click", (ev) => this._onClick(ev));
  }

  setConfig(config) {
    if (!config) { report(`${this.localName}: missing config`, this._hass); throw new Error("Missing config"); }
    this.config = config;
    this._last = null;
    if (this._hass) this._render();
  }

  set hass(hass) {
    this._hass = hass;
    if (!this.config) return; // HA may hand us hass before setConfig
    const ids = this.entities().filter(Boolean);
    const snap = ids.map((id) => hass.states[id]);
    if (this._last && snap.every((s, i) => s === this._last[i])) return;
    this._last = snap;
    this._render();
  }
  get hass() { return this._hass; }

  connectedCallback() {
    // Relative times ("4 min ago") go stale without a state change.
    this._tick = setInterval(() => this._render(), 60_000);
  }
  disconnectedCallback() { clearInterval(this._tick); }

  getCardSize() { return 6; }
  getGridOptions() { return { columns: 12 }; }

  // --- state helpers -----------------------------------------------------
  st(id) { const s = id && this._hass?.states[id]; return s && !BAD.has(s.state) ? s.state : null; }
  obj(id) { return id ? this._hass?.states[id] ?? null : null; }
  attr(id, a) { return this.obj(id)?.attributes?.[a] ?? null; }
  num(id) { const v = parseFloat(this.st(id)); return Number.isFinite(v) ? v : null; }
  on(id) { const s = this.st(id); return s == null ? null : s === "on"; }
  minutesSince(id) {
    const o = this.obj(id);
    if (!o || BAD.has(o.state)) return null;
    return (Date.now() - new Date(o.last_changed).getTime()) / 60_000;
  }
  // Minutes since Frigate last saw a person on this camera entity; null if unknown.
  minutesSincePerson(cameraEntity) {
    const times = personTimes(this._hass, this._personListener ??= () => this._render());
    const cam = this.attr(cameraEntity, "camera_name");
    const t = times && cam ? times[cam] : null;
    return t ? Math.max(0, (Date.now() / 1000 - t) / 60) : null;
  }
  name(id, fallback) { return fallback ?? this.attr(id, "friendly_name") ?? id; }

  call(domain, service, data) { return this._hass.callService(domain, service, data); }
  moreInfo(entityId) {
    this.dispatchEvent(new CustomEvent("hass-more-info", { detail: { entityId }, bubbles: true, composed: true }));
  }

  // --- rendering ---------------------------------------------------------
  _render() {
    if (!this._hass || !this.config) return;
    let html;
    try { html = this.render(); }
    catch (e) {
      html = `<div class="card"><div class="eyebrow">Stonebridge card error</div><div class="sub">${esc(e.message)}</div></div>`;
      if (!this._reported) { this._reported = true; report(`${this.localName} render failed: ${e.stack ?? e}`, this._hass); }
    }
    this.shadowRoot.innerHTML = `<style>${theme}${this.styles?.() ?? ""}</style>${html}`;
    this.afterRender?.();
  }

  // Two-tap confirmation for actions listed in `sensitive`.
  pendingLabel(action, normal, confirm) {
    return this._pending?.action === action ? confirm : normal;
  }
  isPending(action) { return this._pending?.action === action; }

  _onClick(ev) {
    const el = ev.composedPath().find((n) => n.dataset?.action);
    if (!el) return;
    const action = el.dataset.action;
    const sensitive = this.constructor.sensitive?.includes(action.split(":")[0]) && el.dataset.safe !== "1";
    if (sensitive) {
      if (this._pending?.action !== action || Date.now() - this._pending.at > 4000) {
        this._pending = { action, at: Date.now() };
        clearTimeout(this._pendingTimer);
        this._pendingTimer = setTimeout(() => { this._pending = null; this._render(); }, 4000);
        this._render();
        return;
      }
      this._pending = null;
      clearTimeout(this._pendingTimer);
    }
    this.handle(action, el);
    this._render();
  }
}

function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function icon(name) { return `<ha-icon icon="${esc(name)}"></ha-icon>`; }

// --- cards/home.js
{


// type: custom:stonebridge-home
// config: alarm, lock, lock_jammed, garage, weather, outside_temp, inside_temp,
//   car_battery, car_location, vacuum, people: [{entity, name}],
//   lights: [entity...], upstairs_lights: [entity...], cameras_person: [{entity, name}],
//   openings: [{entity, name}] (optional, for future contact sensors)
class StonebridgeHome extends SbCard {
  entities() {
    const c = this.config;
    return [c.alarm, c.lock, c.lock_jammed, c.garage, c.weather, c.outside_temp, c.inside_temp, c.car_battery,
      c.car_location, c.vacuum, "sun.sun", ...(c.people ?? []).map((p) => p.entity), ...(c.lights ?? []),
      ...(c.cameras_person ?? []).map((p) => p.entity), ...(c.openings ?? []).map((o) => o.entity)];
  }

  render() {
    const c = this.config;
    const alarm = this.st(c.alarm), lock = this.st(c.lock), garage = this.st(c.garage);
    const personNow = (c.cameras_person ?? []).find((p) => this.on(p.entity));
    const openings = (c.openings ?? []).map((o) => ({ name: o.name, open: this.on(o.entity) }));
    const inside = this.num(c.inside_temp) ?? this.attr(c.inside_temp, "current_temperature");
    const head = homeHeadline({ alarm, lock, jammed: this.on(c.lock_jammed), garage, personNow: personNow?.name.toLowerCase(), insideTemp: inside, openings });
    const night = this.st("sun.sun") === "below_horizon";
    const lightsOn = (c.lights ?? []).filter((l) => this.on(l));
    const upstairsLit = (c.upstairs_lights ?? []).some((l) => this.on(l));
    const outside = this.num(c.outside_temp);
    const cond = this.st(c.weather);
    const who = whoIsHome((c.people ?? []).map((p) => ({ name: p.name, state: this.st(p.entity) })));
    const carPct = this.num(c.car_battery);
    const vac = this.st(c.vacuum);
    const garageWord = garage ? garage[0].toUpperCase() + garage.slice(1) : "—";

    const sub = [head.sub, carPct != null ? `Car is ${this.st(c.car_location) === "home" ? "home" : "out"} at ${Math.round(carPct)}%.` : null].filter(Boolean).join(" ");

    return `
    <div class="stack">
      <div class="card navy" style="padding:0">
        <div style="display:flex;justify-content:space-between;padding:16px 18px 0">
          <span style="font-size:20px">${greeting(new Date().getHours())}</span>
          <span class="sub">${outside != null ? `${Math.round(outside)}°` : ""}${cond ? ` · ${esc(cond.replace(/-/g, " "))}` : ""}</span>
        </div>
        ${house({ night, upstairsLit, garageOpen: garage === "open", locked: lock === "locked", tone: head.tone })}
        <div style="padding:14px 18px 18px">
          <div class="headline" style="display:flex;align-items:center"><span class="dot tone-${head.tone}"></span>${esc(head.text)}</div>
          <div class="sub">${esc(sub)}</div>
        </div>
      </div>
      <div class="grid g3">
        ${tile("alarm", alarm && alarm !== "disarmed" ? "armed" : "", "mdi:shield-home", alarmWord(alarm) ? cap(alarmWord(alarm)) : "—", "Alarm")}
        ${tile("lock", lock === "locked" ? "ok" : lock === "unlocked" ? "warn" : "", lock === "unlocked" ? "mdi:lock-open-variant" : "mdi:lock", lock ? cap(lock) : "—", "Front door")}
        ${tile("garage", garage === "closed" ? "ok" : garage ? "warn" : "", garage === "closed" ? "mdi:garage" : "mdi:garage-open", garageWord, "Garage")}
        ${tile("vacuum", "", "mdi:robot-vacuum", vac ? cap(vac) : "—", "Roomba")}
        ${tile("lights", lightsOn.length ? "" : "", "mdi:lightbulb-group", lightsOn.length ? `${lightsOn.length} on` : "All off", "Lights")}
        ${tile("people", who.tone === "ok" ? "ok" : "", "mdi:account-multiple", who.text, who.sub)}
      </div>
    </div>`;
  }

  handle(action) {
    const c = this.config;
    const map = { alarm: c.alarm, lock: c.lock, garage: c.garage, vacuum: c.vacuum, people: c.people?.[0]?.entity };
    if (action === "lights") {
      // HA's own navigate(): push the path, then tell the router.
      history.pushState(null, "", c.lights_path ?? "/stonebridge-home/lights");
      window.dispatchEvent(new CustomEvent("location-changed"));
      return;
    }
    if (map[action]) this.moreInfo(map[action]);
  }
}

const cap = (s) => s[0].toUpperCase() + s.slice(1);

function tile(action, cls, ic, big, small) {
  return `<button class="tile ${cls}" data-action="${action}">${icon(ic)}<b>${esc(big)}</b><small>${esc(small)}</small></button>`;
}

function house({ night, upstairsLit, garageOpen, locked, tone }) {
  const sky = night ? ["#16244a", "#1c2d55"] : ["#3f6fa8", "#7fa9d6"];
  const wall = night ? "#25365a" : "#4a5f86";
  const roof = night ? "#2c3d63" : "#3b4f78";
  const win = night ? "#3a4d76" : "#9cc3e6";
  const lit = "#f2c27a";
  const toneCol = { ok: "#5fd4bf", warn: "#f2b45a", alert: "#e86a6a", info: "#9fb3d8" }[tone];
  return `
  <svg viewBox="0 0 360 190" width="100%" style="display:block" aria-hidden="true">
    <defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${sky[0]}"/><stop offset="1" stop-color="${sky[1]}"/></linearGradient></defs>
    <rect width="360" height="190" fill="url(#sky)"/>
    ${night
      ? `<g fill="#fff" opacity=".7"><circle cx="40" cy="22" r="1.2"/><circle cx="120" cy="14" r="1"/><circle cx="210" cy="30" r="1.3"/><circle cx="300" cy="58" r="1"/><circle cx="250" cy="10" r="1"/></g>
         <path d="M318 26a14 14 0 1 0 10 24a11 11 0 1 1 -10 -24z" fill="#f4ecd0"/>`
      : `<circle cx="318" cy="36" r="16" fill="#ffe29a"/><circle cx="318" cy="36" r="26" fill="#ffe29a" opacity=".2"/>`}
    <polygon points="70,82 180,40 290,82" fill="${roof}" stroke="#4a5f8c"/>
    <rect x="70" y="82" width="220" height="90" fill="${wall}" stroke="#4a5f8c"/>
    <rect x="88" y="94" width="40" height="28" fill="${upstairsLit && night ? lit : win}"/>
    <rect x="160" y="94" width="40" height="28" fill="${upstairsLit && night ? lit : win}" opacity=".95"/>
    <rect x="232" y="94" width="40" height="28" fill="${win}"/>
    ${garageOpen
      ? `<rect x="84" y="134" width="110" height="38" fill="#0d1424" stroke="#f2b45a"/><rect x="84" y="134" width="110" height="8" fill="#33476f" stroke="#f2b45a"/>`
      : `<rect x="84" y="134" width="110" height="38" fill="#33476f" stroke="#52689a"/>
         <g stroke="#52689a"><line x1="84" y1="144" x2="194" y2="144"/><line x1="84" y1="154" x2="194" y2="154"/><line x1="84" y1="164" x2="194" y2="164"/></g>`}
    <rect x="240" y="132" width="24" height="40" fill="#33476f" stroke="#52689a"/>
    <circle cx="259" cy="153" r="2.6" fill="${locked ? "#5fd4bf" : "#f2b45a"}"/>
    <rect x="228" y="140" width="6" height="10" rx="2" fill="${night ? "#f2b45a" : "#8090a8"}"/>
    <rect x="0" y="172" width="360" height="18" fill="${night ? "#141d33" : "#2d3e5c"}"/>
    <circle cx="20" cy="180" r="4" fill="${toneCol}"/>
  </svg>`;
}

customElements.define("stonebridge-home", StonebridgeHome);

}
// --- cards/security.js
{


// type: custom:stonebridge-security
// config: alarm, lock, lock_jammed, garage, garage_close_script, garage_remotes,
//   cameras_person: [{entity, name}], openings: [{entity, name}] (optional)
class StonebridgeSecurity extends SbCard {
  static sensitive = ["disarm", "unlock", "garage_open"];

  entities() {
    const c = this.config;
    return [c.alarm, c.lock, c.lock_jammed, c.lock_battery, c.garage, c.garage_remotes,
      ...(c.cameras_person ?? []).map((p) => p.entity), ...(c.openings ?? []).map((o) => o.entity)];
  }

  lastPerson() {
    let best = null;
    for (const p of this.config.cameras_person ?? []) {
      if (this.on(p.entity)) return { camera: `the ${p.name.toLowerCase()} camera`, minutes: 0, now: true };
      const m = p.camera ? this.minutesSincePerson(p.camera) : null;
      if (m != null && (!best || m < best.minutes)) best = { camera: `the ${p.name.toLowerCase()} camera`, minutes: m };
    }
    return best;
  }

  render() {
    const c = this.config;
    const alarm = this.st(c.alarm), lock = this.st(c.lock), garage = this.st(c.garage);
    const jammed = this.on(c.lock_jammed);
    const openings = (c.openings ?? []).map((o) => ({ name: o.name, open: this.on(o.entity) }));
    const last = this.lastPerson();
    const head = securityHeadline({ alarm, lock, jammed, garage, lastPerson: last, openings });
    const remotes = this.st(c.garage_remotes);
    const col = (ok) => (ok == null ? "#6b7486" : ok ? "#5fd4bf" : "#f2b45a");
    const personCol = last?.now ? "#e86a6a" : last && last.minutes < 30 ? "#9fb3d8" : "#5fd4bf";
    const alarmLabel = { disarmed: "Disarmed", armed_home: "Armed home", armed_away: "Armed away", armed_night: "Armed night", triggered: "TRIGGERED", pending: "Pending", arming: "Arming" }[alarm] ?? "—";
    const openCount = openings.filter((o) => o.open).length;

    const node = (x, y, colr, ic, label, labelY = y + 36) => `
      <circle cx="${x}" cy="${y}" r="20" fill="#132042" stroke="${colr}" stroke-width="2"/>
      <foreignObject x="${x - 12}" y="${y - 12}" width="24" height="24"><div xmlns="http://www.w3.org/1999/xhtml" style="color:${colr};display:grid;place-items:center;height:24px">${icon(ic)}</div></foreignObject>
      <text x="${x}" y="${labelY}" fill="${colr === "#5fd4bf" ? "#9aa4b5" : colr}" font-size="12" text-anchor="middle">${esc(label)}</text>`;

    return `
    <div class="stack">
      <div class="card navy">
        <svg viewBox="0 0 320 250" width="100%" style="--mdc-icon-size:16px">
          <circle cx="160" cy="125" r="100" fill="none" stroke="#2f4470" stroke-dasharray="2 8"/>
          <circle cx="160" cy="118" r="58" fill="#132042" stroke="${alarm === "triggered" ? "#e86a6a" : alarm && alarm !== "disarmed" ? "#e86a6a88" : "#30477a"}" stroke-width="${alarm && alarm !== "disarmed" ? 3 : 1}"/>
          <path d="M160 84 l28 11 v22 c0 21 -13 34 -28 40 c-15 -6 -28 -19 -28 -40 v-22z" fill="#1a2b52" stroke="#9fb3d8" stroke-width="2"/>
          <text x="160" y="204" text-anchor="middle" fill="#e9edf3" font-size="22" font-weight="600">${alarmLabel}</text>
          <text x="160" y="224" text-anchor="middle" fill="#9aa4b5" font-size="12">Alarmo</text>
          ${node(160, 26, col(lock == null ? null : lock === "locked" && !jammed), "mdi:lock", jammed ? "Jammed" : lock === "unlocked" ? "Unlocked" : "Front lock", 62)}
          ${node(268, 96, col(garage == null ? null : garage === "closed"), "mdi:garage", garage === "closed" ? "Garage" : "Garage open")}
          ${node(268, 186, personCol, "mdi:cctv", last?.now ? "Person now" : last && last.minutes < 30 ? relTime(last.minutes) : "Cameras")}
          ${node(52, 96, col(remotes == null ? null : true), "mdi:remote", remotes === "locked" ? "Remotes off" : "Remotes")}
          ${node(52, 186, c.openings?.length ? col(!openCount) : "#6b7486", "mdi:window-closed-variant", c.openings?.length ? (openCount ? `${openCount} open` : "Shut") : "No sensors")}
        </svg>
        <div class="headline" style="font-size:21px">${esc(head.text)}</div>
        ${head.sub ? `<div class="sub">${esc(head.sub)}</div>` : ""}
      </div>
      <div class="seg">
        <button data-action="arm_home" class="${alarm === "armed_home" ? "on" : ""}">${icon("mdi:shield-home")}Home</button>
        <button data-action="arm_away" class="${alarm === "armed_away" ? "on" : ""}">${icon("mdi:shield-lock")}Away</button>
        <button data-action="disarm" class="${alarm === "disarmed" ? "on" : ""} ${this.isPending("disarm") ? "pending" : ""}">${icon("mdi:shield-off")}${this.pendingLabel("disarm", "Disarm", "Tap again")}</button>
      </div>
      <div class="card" style="padding:4px 18px">
        ${this.row(lock === "locked" ? "ok" : lock ? "warn" : null, jammed ? "Front door — JAMMED" : "Front door", lock ? `${cap(lock)}${this.battery()}` : "—", lock === "locked" ? "unlock" : "lock", lock === "locked" ? this.pendingLabel("unlock", "Unlock", "Tap again") : "Lock", jammed ? "alert" : null)}
        ${this.row(garage === "closed" ? "ok" : garage ? "warn" : null, "Garage door", garage ? cap(garage) : "—", garage === "closed" ? "garage_open" : "garage_close", garage === "closed" ? this.pendingLabel("garage_open", "Open", "Tap again") : "Close")}
        ${this.row(remotes ? "ok" : null, "Garage remotes", remotes === "locked" ? "Disabled" : remotes ? "Allowed" : "—", "remotes", remotes === "locked" ? "Allow" : "Disable")}
        ${(c.openings ?? []).map((o) => { const v = this.on(o.entity); return this.row(v == null ? null : v ? "warn" : "ok", o.name, v == null ? "—" : v ? "Open" : "Shut"); }).join("")}
      </div>
    </div>`;
  }

  battery() {
    const b = this.num(this.config.lock_battery) ?? this.attr(this.config.lock, "battery_level");
    return b != null ? ` · ${Math.round(b)}% battery` : "";
  }

  row(tone, label, value, action, btn, forceTone) {
    const t = forceTone ?? tone;
    const pend = action && this.isPending(action);
    return `<div class="row"><span><span class="dot ${t ? `tone-${t}` : "unavail"}"></span>${esc(label)}</span>
      <span style="display:flex;align-items:center;gap:10px"><span class="${t ? `tone-${t}` : "unavail"}">${esc(value)}</span>
      ${action ? `<button class="chip ${pend ? "warn pending" : "mute"}" style="background:none;cursor:pointer;font:inherit;font-size:13px" data-action="${action}">${esc(btn)}</button>` : ""}</span></div>`;
  }

  handle(action) {
    const c = this.config;
    switch (action) {
      case "arm_home": return this.call("alarm_control_panel", "alarm_arm_home", { entity_id: c.alarm });
      case "arm_away": return this.call("alarm_control_panel", "alarm_arm_away", { entity_id: c.alarm });
      case "disarm": return this.call("alarm_control_panel", "alarm_disarm", { entity_id: c.alarm });
      case "lock": return this.call("lock", "lock", { entity_id: c.lock });
      case "unlock": return this.call("lock", "unlock", { entity_id: c.lock });
      case "garage_open": return this.call("cover", "open_cover", { entity_id: c.garage });
      case "garage_close": return c.garage_close_script
        ? this.call("script", "turn_on", { entity_id: c.garage_close_script })
        : this.call("cover", "close_cover", { entity_id: c.garage });
      case "remotes": return this.call("lock", this.st(c.garage_remotes) === "locked" ? "unlock" : "lock", { entity_id: c.garage_remotes });
    }
  }
}

const cap = (s) => s[0].toUpperCase() + s.slice(1);
customElements.define("stonebridge-security", StonebridgeSecurity);

}
// --- cards/cameras.js
{



// type: custom:stonebridge-cameras
// config: cameras: [{camera, person, name}]  — first one is shown large and live.
//
// Unlike the other cards this one never replaces its whole shadow DOM: the main
// camera lives in a container built once, and only the headline, badges and
// snapshot grid are re-rendered.
//
// Live video is OFF by default (`live: true` to enable): HA reaches Frigate's
// RTSP restream on :8554, which is not reachable from HA on this network, so a
// live view renders blank. The main camera is a 2-second snapshot instead.
class StonebridgeCameras extends SbCard {
  entities() {
    return (this.config.cameras ?? []).flatMap((c) => [c.camera, c.person]);
  }

  connectedCallback() {
    super.connectedCallback();
    // entity_picture carries a rotating token; refresh snapshots every 10 s.
    this._snap = setInterval(() => this._refreshSnapshots(), 10_000);
    this._mainSnap = setInterval(() => this._refreshSnapshots("main"), 2_000);
  }
  disconnectedCallback() { super.disconnectedCallback(); clearInterval(this._snap); clearInterval(this._mainSnap); }

  set hass(h) { super.hass = h; if (this._liveCard) this._liveCard.hass = h; }
  get hass() { return super.hass; }

  info() {
    return (this.config.cameras ?? []).map((c) => ({
      ...c,
      personNow: this.on(c.person),
      minutesSincePerson: this.minutesSincePerson(c.camera),
    }));
  }

  _render() {
    if (!this.hass || !this.config) return;
    const root = this.shadowRoot;
    if (!this._built) {
      root.innerHTML = `<style>${theme}${this.styles()}</style>
        <div class="stack">
          <div class="card" id="head"></div>
          <div class="cam big" id="main"><div id="live"></div><em id="mainbadge"></em><b id="mainname"></b></div>
          <div class="grid g2" id="grid"></div>
        </div>`;
      this._built = true;
      this._mountLive();
    }
    const info = this.info();
    const [main, ...rest] = info;
    const head = camerasHeadline(info);
    root.getElementById("head").innerHTML = `
      <div class="eyebrow">Frigate · ${info.length} cameras</div>
      <div class="headline">${esc(head.text)}</div>
      ${head.sub ? `<div class="sub">${esc(head.sub)}</div>` : ""}`;
    const mainEl = root.getElementById("main");
    if (main) {
      mainEl.dataset.action = `open:${main.camera}`;
      root.getElementById("mainname").textContent = this.config.live ? `${main.name} (live)` : main.name;
      this._badge(root.getElementById("mainbadge"), main);
    } else mainEl.hidden = true;
    root.getElementById("grid").innerHTML = rest.map((c) => `
      <div class="cam" data-action="open:${esc(c.camera)}">
        ${this._img(c.camera)}<em data-badge="${esc(c.camera)}"></em><b>${esc(c.name)}</b>
      </div>`).join("");
    rest.forEach((c) => this._badge(root.querySelector(`[data-badge="${CSS.escape(c.camera)}"]`), c));
  }

  _badge(el, c) {
    if (!el) return;
    el.className = c.personNow ? "hot" : "";
    el.textContent = c.personNow ? "Person · now" : c.minutesSincePerson != null ? relTime(c.minutesSincePerson).replace(" ago", "") : "";
    el.hidden = !el.textContent;
  }

  _src(cam) {
    const pic = this.attr(cam, "entity_picture");
    return pic ? `${pic}${pic.includes("?") ? "&" : "?"}t=${Date.now()}` : null;
  }

  _img(cam, group = "grid") {
    const src = this._src(cam);
    return src ? `<img data-cam="${esc(cam)}" data-group="${group}" src="${esc(src)}" alt="">` : `<div class="nofeed">No feed</div>`;
  }

  _refreshSnapshots(group = "grid") {
    this.shadowRoot.querySelectorAll(`img[data-group="${group}"]`).forEach((img) => {
      if (!img.complete) return; // previous frame still loading — don't pile up requests
      const src = this._src(img.dataset.cam);
      if (src) img.src = src;
    });
  }

  async _mountLive() {
    const slot = this.shadowRoot.getElementById("live");
    const main = this.config.cameras?.[0];
    if (!slot || !main) return;
    if (!this.config.live) { slot.innerHTML = this._img(main.camera, "main"); return; }
    try {
      const helpers = await window.loadCardHelpers?.();
      if (helpers) {
        this._liveCard = await helpers.createCardElement({
          type: "picture-entity", entity: main.camera, camera_view: "live", show_name: false, show_state: false,
          tap_action: { action: "none" }, // our wrapper opens more-info
        });
        this._liveCard.hass = this.hass;
        slot.replaceChildren(this._liveCard);
        return;
      }
    } catch (e) { console.warn("stonebridge: live view unavailable, using snapshots", e); }
    slot.innerHTML = this._img(main.camera, "main");
  }

  setConfig(config) {
    // A new camera list means a new live card.
    this._built = false;
    this._liveCard = null;
    super.setConfig(config);
  }

  handle(action) {
    if (action.startsWith("open:")) this.moreInfo(action.slice(5));
  }

  // The base re-renders after every tap; nothing here changes on tap.
  _onClick(ev) {
    const el = ev.composedPath().find((n) => n.dataset?.action);
    if (el) this.handle(el.dataset.action);
  }

  styles() {
    return `
    .cam { border-radius: 18px; height: 104px; position: relative; overflow: hidden; background: linear-gradient(135deg,#2b3240,#161a22); cursor: pointer; }
    .cam.big { height: auto; min-height: 190px; }
    .cam img { width: 100%; height: 100%; object-fit: cover; display: block; }
    #live > * { --ha-card-border-radius: 0; --ha-card-border-width: 0; display: block; }
    .cam b { position: absolute; left: 10px; bottom: 8px; font-weight: 500; font-size: 13px; z-index: 1; text-shadow: 0 1px 3px #000; pointer-events: none; }
    .cam em { position: absolute; right: 8px; top: 8px; font-style: normal; font-size: 11px; background: #000a; border-radius: 99px; padding: 3px 8px; z-index: 1; }
    .cam em.hot { background: #e86a6add; }
    .nofeed { display: grid; place-items: center; height: 100%; min-height: 104px; color: var(--sb-dim); font-size: 13px; }`;
  }
}

customElements.define("stonebridge-cameras", StonebridgeCameras);

}
// --- cards/car.js
{


// type: custom:stonebridge-car
// config: name, battery, range, charging, charge_cable, charge_limit, time_to_full,
//   location, lock, sentry, climate, inside_temp, outside_temp, trunk, frunk,
//   charge_port, windows (cover), flash, garage_car_inside (binary_sensor),
//   doors: [binary_sensor...], precondition_enabled, precondition_pending,
//   update, tyres: {fl, fr, rl, rr, recommended} (optional; hidden until given)
class StonebridgeCar extends SbCard {
  static sensitive = ["trunk_open"];

  entities() {
    const c = this.config;
    return [c.battery, c.range, c.charging, c.charge_cable, c.charge_limit, c.time_to_full, c.location, c.lock,
      c.sentry, c.climate, c.inside_temp, c.outside_temp, c.trunk, c.frunk, c.charge_port, c.windows,
      c.garage_car_inside, c.precondition_enabled, c.precondition_pending, c.update, c.status,
      ...(c.doors ?? []), ...Object.values(c.tyres ?? {})];
  }

  render() {
    const c = this.config;
    const battery = this.num(c.battery), range = this.num(c.range), limit = this.num(c.charge_limit);
    const lock = this.st(c.lock), trunk = this.st(c.trunk), frunk = this.st(c.frunk), port = this.st(c.charge_port);
    const climate = this.st(c.climate), sentry = this.st(c.sentry), windows = this.st(c.windows);
    const doorsOpen = (c.doors ?? []).some((d) => this.on(d));
    const open = [trunk === "open" && "Trunk", frunk === "open" && "Frunk", doorsOpen && "A door", windows === "open" && "Windows"].filter(Boolean);
    // Tesla Fleet reports time-to-full as a timestamp sensor.
    const ttfAt = Date.parse(this.st(c.time_to_full) ?? "");
    const ttfMin = Number.isFinite(ttfAt) ? Math.max(0, (ttfAt - Date.now()) / 60_000) : null;
    const head = carHeadline({
      location: this.st(c.location), garageCarInside: this.on(c.garage_car_inside), charging: this.st(c.charging),
      cable: this.on(c.charge_cable), battery: battery != null ? Math.round(battery) : "—", limit: limit ?? "—",
      minutesToFull: ttfMin, open,
    });
    const asleep = this.on(c.status) === false;
    const inside = this.num(c.inside_temp), outside = this.num(c.outside_temp);
    const upd = this.st(c.update) === "on" ? this.attr(c.update, "latest_version") : null;
    const tyres = c.tyres ? Object.fromEntries(["fl", "fr", "rl", "rr"].map((k) => [k, this.num(c.tyres[k])])) : null;
    const rec = c.tyres?.recommended;
    const tyreLow = (v) => v != null && rec && v < rec - 3;
    const precond = this.on(c.precondition_enabled);
    const pending = this.num(c.precondition_pending);

    const chip = (ok, label, cls = "") => `<span class="chip ${ok === false ? "warn" : ok == null ? "mute" : cls}">${esc(label)}</span>`;
    const btn = (action, ic, label, on) => `<button class="round ${on ? "on" : ""} ${this.isPending(action) ? "pending" : ""}" data-action="${action}"><span class="btn">${icon(ic)}</span><span>${esc(label)}</span></button>`;

    return `
    <div class="stack">
      <div class="card navy">
        <div style="display:flex;justify-content:space-between;align-items:start">
          <div><div class="eyebrow">${esc(c.name ?? "Car")}</div><div class="headline">${esc(head.text)}</div></div>
          <span class="chip mute">● ${asleep ? "Asleep" : "Awake"}</span>
        </div>
        ${carSvg({ trunk: trunk === "open", frunk: frunk === "open", doors: doorsOpen, locked: lock === "locked", tyres, tyreLow })}
        <div style="display:flex;justify-content:space-between;align-items:end;margin:6px 0 12px">
          <span class="big">${battery != null ? Math.round(battery) : "—"}<span style="font-size:22px">%</span></span>
          <span style="text-align:right"><span style="font-size:24px">${range != null ? Math.round(range) : "—"} mi</span><br><span class="sub">estimated range</span></span>
        </div>
        <div class="bar"><div style="width:${Math.min(100, battery ?? 0)}%"></div>${limit != null ? `<span class="mark" style="left:${limit}%"></span>` : ""}</div>
        <div class="sub ${head.tone === "warn" ? "tone-warn" : ""}" style="margin:14px 0 12px">${esc(head.sub)}</div>
        <div class="chips">
          ${chip(lock == null ? null : lock === "locked", lock === "locked" ? "Locked" : lock ? "Unlocked" : "Lock —")}
          ${chip(sentry == null ? null : true, sentry === "on" ? "Sentry on" : "Sentry off", sentry === "on" ? "" : "mute")}
          ${chip((c.doors ?? []).length ? !doorsOpen : null, doorsOpen ? "Door open" : "Doors shut")}
          ${chip(windows == null ? null : windows === "closed", windows === "closed" ? "Windows up" : "Windows open")}
          ${chip(climate == null ? null : true, climate && climate !== "off" ? "Climate on" : "Climate off", climate && climate !== "off" ? "" : "mute")}
          ${upd ? `<span class="chip" style="border-color:#4d3f7a;color:#a98bff;background:#221c36">Update ${esc(upd)}</span>` : ""}
        </div>
        <div class="sub" style="margin-top:12px">${[
          inside != null ? `${Math.round(inside)}° inside` : null,
          outside != null ? `${Math.round(outside)}° outside` : null,
        ].filter(Boolean).join(" · ")}</div>
      </div>
      ${c.precondition_enabled ? `
      <div class="card">
        <div class="eyebrow">Calendar preconditioning</div>
        <div class="headline" style="font-size:19px">${precond ? (pending ? `${pending} warm-up${pending === 1 ? "" : "s"} scheduled.` : "Watching your calendar.") : "Off."}</div>
        <div class="sub">${precond ? "Warms the car before calendar events." : "Manual scheduling still works."}</div>
        <div style="margin-top:12px"><button class="chip ${precond ? "" : "mute"}" style="background:none;cursor:pointer;font:inherit;font-size:13px" data-action="precond">${precond ? "Turn off" : "Turn on"}</button></div>
      </div>` : ""}
      <div class="grid g4">
        ${btn("climate", "mdi:fan", climate && climate !== "off" ? "Climate on" : "Climate", climate && climate !== "off")}
        ${btn(trunk === "open" ? "trunk_close" : "trunk_open", "mdi:car-back", this.pendingLabel("trunk_open", trunk === "open" ? "Close trunk" : "Trunk", "Tap again"), trunk === "open")}
        ${btn("port", "mdi:ev-plug-tesla", port === "open" ? "Close port" : "Port", port === "open")}
        ${btn("flash", "mdi:car-light-high", "Flash", false)}
      </div>
    </div>`;
  }

  handle(action) {
    const c = this.config;
    switch (action) {
      case "climate": return this.call("climate", this.st(c.climate) === "off" ? "turn_on" : "turn_off", { entity_id: c.climate });
      case "trunk_open": return this.call("cover", "open_cover", { entity_id: c.trunk });
      case "trunk_close": return this.call("cover", "close_cover", { entity_id: c.trunk });
      case "port": return this.call("cover", this.st(c.charge_port) === "open" ? "close_cover" : "open_cover", { entity_id: c.charge_port });
      case "flash": return this.call("button", "press", { entity_id: c.flash });
      case "precond": return this.call("input_boolean", "toggle", { entity_id: c.precondition_enabled });
    }
  }
}

function carSvg({ trunk, frunk, doors, locked, tyres, tyreLow }) {
  const t = (x, y, v, anchor) => v == null ? "" : `
    <text x="${x}" y="${y}" text-anchor="${anchor}" fill="${tyreLow(v) ? "#f2b45a" : "#5fd4bf"}" font-size="26">${Math.round(v)}<tspan font-size="12"> psi</tspan></text>
    ${tyreLow(v) ? `<text x="${x}" y="${y + 18}" text-anchor="${anchor}" fill="#f2b45a" font-size="12">Low</text>` : ""}`;
  const amber = "#f2b45a";
  return `
  <svg viewBox="0 0 320 220" width="100%" aria-hidden="true">
    ${tyres ? `${t(22, 50, tyres.fl, "start")}${t(298, 50, tyres.fr, "end")}${t(22, 170, tyres.rl, "start")}${t(298, 170, tyres.rr, "end")}` : ""}
    <rect x="118" y="10" width="84" height="200" rx="34" fill="#cfd5de" stroke="${doors ? amber : "none"}" stroke-width="3"/>
    <rect x="128" y="20" width="64" height="20" rx="8" fill="${frunk ? amber : "#b9c1cc"}"/>
    <rect x="128" y="44" width="64" height="40" rx="12" fill="#2a3445"/>
    <rect x="128" y="92" width="64" height="58" rx="8" fill="#334055"/>
    <rect x="132" y="158" width="56" height="28" rx="10" fill="#2a3445"/>
    <rect x="130" y="190" width="60" height="14" rx="6" fill="${trunk ? amber : "#b9c1cc"}"/>
    <g fill="#5fd4bf44"><rect x="110" y="40" width="10" height="30" rx="4"/><rect x="200" y="40" width="10" height="30" rx="4"/>
      <rect x="110" y="150" width="10" height="30" rx="4"/><rect x="200" y="150" width="10" height="30" rx="4"/></g>
    <foreignObject x="148" y="109" width="24" height="24"><div xmlns="http://www.w3.org/1999/xhtml" style="color:${locked ? "#9fb3d8" : amber};--mdc-icon-size:20px;display:grid;place-items:center">${icon(locked ? "mdi:lock" : "mdi:lock-open-variant")}</div></foreignObject>
  </svg>`;
}

customElements.define("stonebridge-car", StonebridgeCar);

}
// --- cards/climate.js
{


// type: custom:stonebridge-climate
// config: thermostat, outside_temp,
//   rooms: [{name, temperature, humidity?, source?}]   <- add new sensors here
//   bill: {to_date, forecast, typical?}                 (optional)
class StonebridgeClimate extends SbCard {
  entities() {
    const c = this.config;
    return [c.thermostat, c.outside_temp, c.bill?.to_date, c.bill?.forecast, c.bill?.typical,
      ...(c.rooms ?? []).flatMap((r) => [r.temperature, r.humidity])];
  }

  render() {
    const c = this.config;
    const t = c.thermostat;
    const a = (k) => this.attr(t, k);
    const mode = this.st(t);
    const head = thermostatHeadline({ mode, action: a("hvac_action"), target: a("temperature"), low: a("target_temp_low"), high: a("target_temp_high") });
    const cur = a("current_temperature");
    const hum = a("current_humidity");
    const preset = a("preset_mode");
    const step = a("target_temp_step") ?? 0.5;
    const single = a("temperature") != null;

    const rooms = (c.rooms ?? []).map((r) => {
      // A room may point at the thermostat itself (climate entity) or at a sensor.
      const temp = r.temperature?.startsWith("climate.") ? this.attr(r.temperature, "current_temperature") : this.num(r.temperature);
      const humidity = r.humidity?.startsWith("climate.") ? this.attr(r.humidity, "current_humidity") : this.num(r.humidity);
      return { ...r, temp, humidity };
    });
    const rh = roomsHeadline(rooms);
    const out = this.num(c.outside_temp);
    const bill = c.bill ? billHeadline({ toDate: this.num(c.bill.to_date), forecast: this.num(c.bill.forecast) }) : null;

    // Arc gauge: 270° sweep, 55°F..85°F
    const frac = cur == null ? 0 : Math.max(0, Math.min(1, (cur - 55) / 30));
    const sweep = 226;
    const arcCol = a("hvac_action") === "heating" ? "#f2b45a" : a("hvac_action") === "cooling" ? "#6aa7ff" : "#9fb3d8";

    return `
    <div class="stack">
      <div class="card">
        <div style="display:flex;gap:16px;align-items:center">
          <svg viewBox="0 0 120 120" width="120" style="flex:none" aria-hidden="true">
            <circle cx="60" cy="60" r="48" fill="none" stroke="#2a303c" stroke-width="10" stroke-dasharray="${sweep} 302" transform="rotate(135 60 60)" stroke-linecap="round"/>
            <circle cx="60" cy="60" r="48" fill="none" stroke="${arcCol}" stroke-width="10" stroke-dasharray="${sweep * frac} 302" transform="rotate(135 60 60)" stroke-linecap="round"/>
            <text x="60" y="66" text-anchor="middle" fill="#e9edf3" font-size="30" font-weight="300">${cur != null ? `${Math.round(cur)}°` : "—"}</text>
            <text x="60" y="84" text-anchor="middle" fill="#9aa4b5" font-size="11">inside</text>
          </svg>
          <div>
            <div class="eyebrow">${esc(c.thermostat_name ?? "Thermostat")}</div>
            <div class="headline">${esc(head.text)}</div>
            <div class="sub">${[mode ? `Mode: ${cap(mode.replace("_", "/"))}` : null, hum != null ? `${hum}% humidity` : null, preset ? `Preset: ${cap(preset)}` : null].filter(Boolean).map(esc).join("<br>")}</div>
          </div>
        </div>
        ${single && mode !== "off" ? `
        <div style="display:flex;align-items:center;justify-content:center;gap:22px;margin-top:14px">
          <button class="round" data-action="down"><span class="btn" style="width:48px;height:48px">${icon("mdi:minus")}</span></button>
          <div style="text-align:center"><div style="font-size:28px">${a("temperature")}°</div><div class="sub">Target</div></div>
          <button class="round" data-action="up"><span class="btn" style="width:48px;height:48px">${icon("mdi:plus")}</span></button>
        </div>` : ""}
        <div class="seg" style="margin-top:14px">
          ${["home", "away", "sleep"].map((p) => `<button data-action="preset:${p}" class="${preset === p ? "on" : ""}">${icon({ home: "mdi:home", away: "mdi:home-export-outline", sleep: "mdi:weather-night" }[p])}${cap(p)}</button>`).join("")}
        </div>
      </div>

      <div class="card">
        <div class="eyebrow">Room by room</div>
        <div class="headline" style="font-size:20px">${esc(rh.text)}</div>
        ${rooms.map((r) => `
          <div class="row">
            <span><span class="dot" style="color:${tempColour(r.temp)}"></span><span>${esc(r.name)}${r.source ? `<br><small class="sub">${esc(r.source)}</small>` : ""}</span></span>
            <span style="display:flex;align-items:center;gap:14px">
              ${r.humidity != null ? `<span class="sub">${Math.round(r.humidity)}% humid</span>` : ""}
              <span style="font-size:24px;min-width:56px;text-align:right">${r.temp != null ? `${Math.round(r.temp)}°` : "—"}</span>
            </span>
          </div>`).join("")}
        ${out != null ? `<div class="row"><span><span class="dot" style="color:${tempColour(out)}"></span>Outside</span><span style="font-size:24px">${Math.round(out)}°</span></div>` : ""}
      </div>

      ${bill ? `
      <div class="card">
        <div class="eyebrow">Electric bill</div>
        <div class="headline" style="font-size:20px">${esc(bill.text)}</div>
        ${bill.sub ? `<div class="sub">${esc(bill.sub)}</div>` : ""}
        ${this.billBar()}
      </div>` : ""}
    </div>`;
  }

  billBar() {
    const b = this.config.bill;
    const to = this.num(b.to_date), fc = this.num(b.forecast);
    if (to == null || !fc) return "";
    return `<div class="bar" style="margin-top:14px"><div style="width:${Math.min(100, (to / fc) * 100)}%"></div></div>`;
  }

  handle(action) {
    const t = this.config.thermostat;
    const step = this.attr(t, "target_temp_step") ?? 0.5;
    const cur = this.attr(t, "temperature");
    if (action === "up" || action === "down") {
      return this.call("climate", "set_temperature", { entity_id: t, temperature: cur + (action === "up" ? step : -step) });
    }
    if (action.startsWith("preset:")) return this.call("climate", "set_preset_mode", { entity_id: t, preset_mode: action.slice(7) });
  }
}

// Blue (62°) → teal → green → yellow → red (80°), matching the concept's scale.
function tempColour(t) {
  if (t == null) return "#6b7486";
  const stops = [[62, "#4a7dff"], [68, "#5fd4bf"], [72, "#9fd88a"], [76, "#f2b45a"], [80, "#e86a6a"]];
  if (t <= stops[0][0]) return stops[0][1];
  for (let i = 1; i < stops.length; i++) if (t <= stops[i][0]) return stops[i][1];
  return stops.at(-1)[1];
}

const cap = (s) => s[0].toUpperCase() + s.slice(1);
customElements.define("stonebridge-climate", StonebridgeClimate);

}
// --- cards/lights.js
{


// type: custom:stonebridge-lights
// config: floors: [{name, lights: [{entity, name, icon?, fan?}]}],
//   scenes: [{entity, name, icon}]
// A light's optional `fan` (switch) shows as a small toggle on its tile.
class StonebridgeLights extends SbCard {
  entities() {
    const c = this.config;
    return [...(c.floors ?? []).flatMap((f) => f.lights.flatMap((l) => [l.entity, l.fan])), ...(c.scenes ?? []).map((s) => s.entity)];
  }

  all() {
    return (this.config.floors ?? []).flatMap((f) => f.lights.map((l) => ({ ...l, floor: f.name, on: this.on(l.entity) })));
  }

  render() {
    const c = this.config;
    const lights = this.all();
    const head = lightsHeadline(lights);
    const onLights = lights.filter((l) => l.on);
    // Not "on since …": HA resets last_changed on restart, so that time can lie.
    const since = onLights.length > 1 ? `${onLights.map((l) => l.name).join(", ")}.` : null;

    return `
    <div class="stack">
      <div class="card">
        <div class="eyebrow">Lights</div>
        <div class="headline">${esc(head.text)}</div>
        ${since ? `<div class="sub">${esc(since)}</div>` : ""}
      </div>
      <div class="grid g4">
        ${(c.scenes ?? []).map((s) => `<button class="round" data-action="scene:${esc(s.entity)}"><span class="btn">${icon(s.icon ?? "mdi:palette")}</span><span>${esc(s.name)}</span></button>`).join("")}
        <button class="round" data-action="all_on"><span class="btn">${icon("mdi:lightbulb-on")}</span><span>All on</span></button>
        <button class="round" data-action="all_off"><span class="btn">${icon("mdi:lightbulb-off")}</span><span>All off</span></button>
      </div>
      ${(c.floors ?? []).map((f) => `
        <div class="section">${esc(f.name)}</div>
        <div class="grid g3">${f.lights.map((l) => this.tile(l)).join("")}</div>`).join("")}
    </div>`;
  }

  tile(l) {
    const on = this.on(l.entity);
    const bri = this.attr(l.entity, "brightness");
    const pct = on && bri != null ? `${Math.round((bri / 255) * 100)}%` : null;
    const fan = l.fan ? this.on(l.fan) : undefined;
    const state = on == null ? "Unavailable" : on ? `On${pct ? ` · ${pct}` : ""}` : "Off";
    return `
      <button class="light ${on ? "on" : ""} ${on == null ? "muted" : ""}" data-action="toggle:${esc(l.entity)}">
        ${icon(l.icon ?? "mdi:lightbulb")}
        <b>${esc(l.name)}</b><small>${esc(state)}</small>
        ${l.fan ? `<span class="fan ${fan ? "on" : ""}" data-action="fan:${esc(l.fan)}">${icon("mdi:fan")}${fan == null ? "—" : fan ? "On" : "Off"}</span>` : ""}
      </button>`;
  }

  handle(action) {
    const [verb, id] = [action.split(":")[0], action.slice(action.indexOf(":") + 1)];
    const ids = this.all().map((l) => l.entity);
    switch (verb) {
      case "toggle": return this.call("light", "toggle", { entity_id: id });
      case "fan": return this.call("switch", "toggle", { entity_id: id });
      case "scene": return this.call("scene", "turn_on", { entity_id: id });
      case "all_on": return this.call("light", "turn_on", { entity_id: ids });
      case "all_off": return this.call("light", "turn_off", { entity_id: ids });
    }
  }

  styles() {
    return `
    .light { border-radius: 18px; padding: 12px; border: 1px solid var(--sb-line); background: var(--sb-card); color: inherit;
      font: inherit; text-align: left; cursor: pointer; display: flex; flex-direction: column; gap: 2px; min-height: 92px;
      -webkit-tap-highlight-color: transparent; }
    .light ha-icon { --mdc-icon-size: 20px; color: var(--sb-dim); }
    .light.on { background: radial-gradient(120% 120% at 20% 0%, #5a4520, #2a2216 60%); border-color: #7a5d2a; }
    .light.on ha-icon { color: #f2c27a; }
    .light b { font-weight: 500; font-size: 14px; margin-top: 4px; }
    .light small { color: var(--sb-muted); font-size: 12px; }
    .light.on small { color: #f2d39a; }
    .fan { margin-top: 6px; display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--sb-muted);
      border: 1px solid var(--sb-line); border-radius: 99px; padding: 2px 8px 2px 4px; align-self: flex-start; }
    .fan ha-icon { --mdc-icon-size: 14px; }
    .fan.on { color: var(--sb-ok); border-color: #2f5a55; }
    .fan.on ha-icon { color: var(--sb-ok); }`;
  }
}

customElements.define("stonebridge-lights", StonebridgeLights);

}